// === Tab: mySketch.js ===
let particles = [];
let time = 0;
// 三种春日花花的颜色：粉、白、蓝
const flowerColors = [
  [255, 160, 200],  // 温柔樱花粉
  [255, 255, 255],  // 纯净白
  [100, 160, 255]   // 清新天空蓝
];

function setup() {
  createCanvas(720, 720);
  // 关闭描边，用填充画星星
  noStroke();
}

function draw() {
  // 春天清新绿色背景，带透明度做拖尾效果
  background(160, 230, 120, 15);
  // 模糊滤镜，营造朦胧流动感
  filter(BLUR);

  // 每帧生成9个粒子，模拟密集的春日花雨
  let i = 9;
  while (i > 0) {
    i--;
    let index = time % (width * 9);
    let px = (time * 99) % width;

    // 随机选择一种花花颜色
    let colorIdx = floor(random(flowerColors.length));

    let obj = {
      x: px,
      y: 0,
      g: 0,          // 垂直加速度
      s: random(3, 6),// 星星大小，增加层次感
      c: flowerColors[colorIdx] // 花花颜色
    };

    particles[index] = obj;
    time++;
  }

  // 更新并绘制所有粒子
  for (let idx = 0; idx < particles.length; idx++) {
    let p = particles[idx];
    if (!p) continue;

    // 粒子逐渐缩小，模拟花瓣飘落消散
    p.s *= 0.997;
    if (p.s < 0.2) continue; // 太小就不画了，优化性能

    // 柏林噪声控制流动轨迹，模拟自然的下落+侧滑
    let Noise = noise(p.x / width, p.y / 9, time / width);

    // 水平运动：噪声高时直落，低时左右侧滑，形成阶梯感
    if (Noise > 0.4) {
      p.x += 0;
    } else {
      p.x += (Noise % 0.1 > 0.05) ? 1 : -1;
      p.g = 0; // 侧滑时重置加速度
    }

    // 垂直运动：噪声高时加速下落，低时缓慢飘落
    if (Noise > 0.4) {
      p.g += 0.5;
      p.y += p.g;
    } else {
      p.y += 0.5;
    }

    // 绘制星星形状的花花
    push();
    translate(p.x, p.y);
    fill(p.c[0], p.c[1], p.c[2], 220); // 带透明度更柔和
    drawStar(0, 0, p.s * 0.5, p.s, 5); // 5角星，更像小花
    pop();
  }
}

// 绘制星星的工具函数
function drawStar(x, y, radius1, radius2, npoints) {
  let angle = TWO_PI / npoints;
  let halfAngle = angle / 2.0;
  beginShape();
  for (let a = 0; a < TWO_PI; a += angle) {
    let sx = x + cos(a) * radius2;
    let sy = y + sin(a) * radius2;
    vertex(sx, sy);
    sx = x + cos(a + halfAngle) * radius1;
    sy = y + sin(a + halfAngle) * radius1;
    vertex(sx, sy);
  }
  endShape(CLOSE);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
